static uint32_t table[256];
    static bool table_computed = false;

    if (!table_computed) {
        for (uint32_t i = 0; i < 256; i++) {
            uint32_t c = i;
            for (int j = 0; j < 8; j++) {
                if (c & 1) {
                    c = 0xEDB88320L ^ (c >> 1);
                } else {
                    c = c >> 1;
                }
            }
            table[i] = c;
        }
        table_computed = true;
    }

    const uint8_t *p = static_cast<const uint8_t *>(buffer);
    while (size--) {
        crc = table[(crc ^ *p++) & 0xFF] ^ (crc >> 8);
    }

    return crc;

